// Set Scale, the transform rules (plan 4.10 and 5.4, tests-first): the two ratio rules, the factor, the epsilon, the position helpers and the
// annotation rotation rule. Every ported test cites its Windows test as `file:line`; a test that is not a 1:1 port says so in its name or its
// comment. The oracle tables (PageScaleTransformOracleData.hpp) were generated by running the REAL Windows functions read-only
// (page_scale_transform.py, overlay.py, annotation.py), see the header of that file.
//
// What differs from the Windows tests on purpose: the Windows tests also feed Python strings / None where a C++ function takes numbers.
// Those rows are dropped (said in the comment of the test); a missing scale (None) is std::nullopt, and a missing sf1 / sf2 inside a pair is 0.
#include "TestHarness.hpp"

#include "Domain/PageScaleTransform.hpp"

#include "PageScaleTransformOracleData.hpp"

#include <cmath>
#include <limits>
#include <optional>
#include <string>
#include <vector>

using namespace ost_domain;
using std::optional;
using std::vector;

namespace
{
    constexpr double kInfinity = std::numeric_limits<double>::infinity();
    constexpr double kNotANumber = std::numeric_limits<double>::quiet_NaN();

    // units_per_sheet_inch as a number (NaN when the pair has none), so that a missing answer fails a CHECK instead of dereferencing an empty optional.
    double units(double sf1, double sf2)
    {
        const std::optional<double> value = units_per_sheet_inch(sf1, sf2);
        return value ? *value : std::numeric_limits<double>::quiet_NaN();
    }

    optional<PageScale> scale(double sf1, double sf2)
    {
        return PageScale{sf1, sf2};
    }

    // Python assertEqual on two floats is exact; the oracle rows are exact doubles as well.
    void check_same_double(double got, double expected)
    {
        if (std::isnan(expected))
            CHECK(std::isnan(got));
        else
            CHECK_EQ(got, expected);
    }
}

// ---- group A: tests/domain/services/test_page_scale_transform.py ------------------------------------------------------------------

// tests/domain/services/test_page_scale_transform.py:10 test_position_factor_matches_page_scale_rescale_rule (assertAlmostEqual).
TEST(SetScale_Transform, PositionFactorMatchesPageScaleRescaleRule)
{
    CHECK_NEAR(position_rescale_factor_between_page_scales(scale(0.125, 12.0), scale(0.1875, 12.0)), 2.0 / 3.0, 1e-7);
}

// tests/domain/services/test_page_scale_transform.py:16 test_zero_source_scale_uses_fallback_identity_source_ratio.
TEST(SetScale_Transform, ZeroSourceScaleUsesFallbackIdentitySourceRatio)
{
    CHECK_EQ(position_rescale_factor_between_page_scales(scale(0.0, 12.0), scale(0.25, 12.0)), 48.0);
}

// tests/domain/services/test_page_scale_transform.py:20 test_rescale_position_preserves_non_numeric_values. ADAPTED: the C++ position holds numbers only, so the
// strings "6" and "label" of the Windows list are not representable; the numeric rows (12.0 x 0.5 = 6.0) are kept, and rescale_position of an empty list is empty.
TEST(SetScale_Transform, RescalePositionMultipliesEveryNumber_AdaptedNumbersOnly)
{
    CHECK_EQ(rescale_position({6.0, 3.0, 12.0}, 0.5), vector<double>({3.0, 1.5, 6.0}));
    CHECK_EQ(rescale_position({}, 0.5), vector<double>());
    CHECK_EQ(rescale_position({1.0, 2.0}, 1.0), vector<double>({1.0, 2.0}));
}

// tests/domain/services/test_page_scale_transform.py:26 test_rescale_position_between_page_scales_returns_copy_when_unchanged.
TEST(SetScale_Transform, RescaleBetweenPageScalesReturnsACopyWhenUnchanged)
{
    const vector<double> position = {1.0, 2.0, 3.0, 4.0};
    const vector<double> scaled = rescale_position_between_page_scales(position, scale(1.0, 12.0), scale(1.0, 12.0));
    CHECK_EQ(scaled, position);
    CHECK(scaled.data() != position.data()); // a copy, not the same buffer
    // the control (not in the Windows test): a changed scale does rescale
    CHECK_EQ(rescale_position_between_page_scales(position, scale(1.0, 12.0), scale(1.0, 6.0)), vector<double>({0.5, 1.0, 1.5, 2.0}));
}

// tests/domain/services/test_page_scale_transform.py:36 test_round_trip_preserves_angles_and_does_not_mutate_snapshots: 20 round trips, exact.
TEST(SetScale_Transform, RoundTripPreservesAnglesAndDoesNotMutateSnapshots)
{
    struct Row
    {
        AnnotationKind kind;
        vector<double> values;
        vector<double> expected_scaled;
    };
    const Row rows[] = {
        {AnnotationKind::Ink, {0.123456789, 96.0, 48.0, 192.0, 96.0}, {0.123456789, 48.0, 24.0, 96.0, 48.0}},
        {AnnotationKind::Rect, {96.0, 48.0, 192.0, 96.0, 0.123456789}, {48.0, 24.0, 96.0, 48.0, 0.123456789}},
        {AnnotationKind::Text, {96.0, 48.0, 192.0, 96.0, 0.123456789, 7.25}, {48.0, 24.0, 96.0, 48.0, 0.123456789, 7.25}},
    };
    for (const Row &row : rows)
    {
        SCOPED_CONTEXT("kind " + std::to_string(static_cast<int>(row.kind)));
        const vector<double> original = row.values;
        vector<double> values = row.values;
        for (int i = 0; i < 20; ++i)
        {
            const vector<double> scaled = rescale_annotation_position_between_page_scales(row.kind, values, scale(1, 96), scale(1, 48));
            CHECK_EQ(values, original);
            CHECK_EQ(scaled, row.expected_scaled);
            values = rescale_annotation_position_between_page_scales(row.kind, scaled, scale(1, 48), scale(1, 96));
            CHECK_EQ(values, original);
        }
    }
}

// tests/domain/services/test_page_scale_transform.py:76 test_ratio_is_second_over_first_with_identity_for_missing_or_unusable_scales. ADAPTED: the Windows
// rows with None / "bad" / "0.5" strings are Python typing; a missing sf1 or sf2 is 0 (`float(x or 0.0)`), so (None, 12) is the row (0, 12). The rows kept:
// (0.125, 12) 96, (2, 1) 0.5, (0, 12) 1, (1, 0) 0 (the Windows (1, []) row is the same missing-sf2 case).
TEST(SetScale_Transform, RatioIsSecondOverFirstWithIdentityForUnusableScales)
{
    CHECK_EQ(page_scale_ratio(0.125, 12.0), 96.0);
    CHECK_EQ(page_scale_ratio(2.0, 1.0), 0.5);
    CHECK_EQ(page_scale_ratio(0.0, 12.0), 1.0);
    CHECK_EQ(page_scale_ratio(1.0, 0.0), 0.0);
    CHECK_EQ(page_scale_ratio(0.5, 2.0), 4.0); // the numeric value of the Windows ("0.5", "2") row
}

// tests/domain/services/test_page_scale_transform.py:91 test_a_missing_second_scale_collapses_the_ratio_to_zero_not_identity ((1, None) and (1, 0)).
TEST(SetScale_Transform, AMissingSecondScaleCollapsesTheRatioToZeroNotIdentity)
{
    CHECK_EQ(page_scale_ratio(1.0, 0.0), 0.0);
    CHECK_EQ(page_scale_ratio(1.0, -0.0), 0.0);
}

// tests/domain/services/test_page_scale_transform.py:97 test_factor_between_scales_is_target_over_source_with_identity_for_degenerate_source: all
// seven rows, None = std::nullopt (a missing sf2 inside a pair is the Windows (1, None) / (1, 0) rows).
TEST(SetScale_Transform, FactorBetweenScalesIsTargetOverSourceWithIdentityForDegenerateSource)
{
    CHECK_EQ(position_rescale_factor_between_page_scales(scale(1, 96), scale(1, 48)), 0.5);
    CHECK_EQ(position_rescale_factor_between_page_scales(std::nullopt, scale(1, 2)), 2.0);
    CHECK_EQ(position_rescale_factor_between_page_scales(scale(1, 2), std::nullopt), 0.5);
    CHECK_EQ(position_rescale_factor_between_page_scales(std::nullopt, std::nullopt), 1.0);
    CHECK_EQ(position_rescale_factor_between_page_scales(scale(1, 0), scale(1, 48)), 1.0);   // a source ratio of 0: no meaningful factor
    CHECK_EQ(position_rescale_factor_between_page_scales(scale(1, 96), scale(1, 0)), 0.0);   // a target ratio of 0 scales everything to zero
}

// tests/domain/services/test_page_scale_transform.py:113 test_unchanged_scales_return_an_untouched_copy_even_for_text_numbers. ADAPTED: numbers only.
TEST(SetScale_Transform, UnchangedScalesReturnAnUntouchedCopy_AdaptedNumbersOnly)
{
    const vector<double> position = {6.0, 2.0};
    const vector<double> scaled = rescale_position_between_page_scales(position, scale(1, 12), scale(1, 12));
    CHECK_EQ(scaled, position);
    CHECK(scaled.data() != position.data());
    // two missing scales are both ratio 1: unchanged
    CHECK_EQ(rescale_position_between_page_scales({1.0, 2.0}, std::nullopt, std::nullopt), vector<double>({1.0, 2.0}));
    // the control (not in the Windows test): a changed scale does rescale
    CHECK_EQ(rescale_position_between_page_scales(position, scale(1, 12), scale(1, 24)), vector<double>({12.0, 4.0}));
}

// tests/domain/services/test_page_scale_transform.py:122 test_changed_scales_multiply_every_numeric_value_and_keep_others. ADAPTED: numbers only (the
// ["4", None, "n"] values of the first row are Python-only; the numeric rows are kept).
TEST(SetScale_Transform, ChangedScalesMultiplyEveryNumber_AdaptedNumbersOnly)
{
    CHECK_EQ(rescale_position_between_page_scales({2.0, 4.0}, scale(1, 12), scale(1, 6)), vector<double>({1.0, 2.0}));
    CHECK_EQ(rescale_position_between_page_scales({1.0, 2.0}, scale(1, 1), scale(1, 3)), vector<double>({3.0, 6.0}));
    CHECK_EQ(rescale_position_between_page_scales({}, scale(1, 1), scale(1, 3)), vector<double>());
}

// tests/domain/services/test_page_scale_transform.py:132 test_a_tiny_factor_difference_is_treated_as_unchanged: 1e-12 is unchanged, 1e-6 is scaled.
TEST(SetScale_Transform, ATinyFactorDifferenceIsTreatedAsUnchanged)
{
    CHECK_EQ(rescale_position_between_page_scales({5.0}, scale(1.0, 1.0), scale(1.0, 1.0 + 1e-12)), vector<double>({5.0}));
    const vector<double> scaled = rescale_position_between_page_scales({5.0}, scale(1.0, 1.0), scale(1.0, 1.0 + 1e-6));
    REQUIRE_EQ(scaled.size(), static_cast<size_t>(1));
    CHECK_NEAR(scaled[0], 5.0 * (1.0 + 1e-6), 1e-7); // assertAlmostEqual: 7 places
    CHECK(scaled[0] != 5.0);
}

// tests/domain/services/test_page_scale_transform.py:142 test_scale_values_are_not_mutated_for_unknown_annotation_types: a hotlink position is scaled,
// the input is not mutated, an unchanged scale gives the input back.
TEST(SetScale_Transform, AnnotationPositionIsNotMutatedAndAnUnchangedScaleReturnsTheInput)
{
    const vector<double> values = {10.0, 20.0, 30.0, 40.0};
    CHECK_EQ(rescale_annotation_position_between_page_scales(AnnotationKind::Hotlink, values, scale(1, 2), scale(1, 4)),
             vector<double>({20.0, 40.0, 60.0, 80.0}));
    CHECK_EQ(values, vector<double>({10.0, 20.0, 30.0, 40.0}));
    CHECK_EQ(rescale_annotation_position_between_page_scales(AnnotationKind::Rect, values, scale(1, 2), scale(1, 2)), values);
}

