// ---- oracle tables (the real Windows functions, generated) --------------------------------------------------------------------------------

// overlay.py:7-19 on every row of kUnitsRows (includes the overflow / underflow of the ratio and the infinite sf1).
TEST(SetScale_Transform, UnitsPerSheetInchMatchesWindowsOnEveryOracleRow)
{
    for (const scale_oracle::UnitsRow &row : scale_oracle::kUnitsRows)
    {
        SCOPED_CONTEXT("sf1 " + ost_test::detail::exact_float(row.sf1) + " sf2 " + ost_test::detail::exact_float(row.sf2));
        const optional<double> got = units_per_sheet_inch(row.sf1, row.sf2);
        CHECK_EQ(got.has_value(), row.valid);
        if (got.has_value() && row.valid)
            CHECK_EQ(*got, row.units);
    }
}

// page_scale_transform.py:9-20 on every row of kRatioRows (lenient rule: sf1 == 0 is ratio 1, a missing sf2 is ratio 0).
TEST(SetScale_Transform, PageScaleRatioMatchesWindowsOnEveryOracleRow)
{
    for (const scale_oracle::RatioRow &row : scale_oracle::kRatioRows)
    {
        SCOPED_CONTEXT("sf1 " + ost_test::detail::exact_float(row.sf1) + " sf2 " + ost_test::detail::exact_float(row.sf2));
        check_same_double(page_scale_ratio(row.sf1, row.sf2), row.ratio);
    }
}

// page_scale_transform.py:23-30 on every row of kFactorRows.
TEST(SetScale_Transform, PositionFactorMatchesWindowsOnEveryOracleRow)
{
    for (const scale_oracle::FactorRow &row : scale_oracle::kFactorRows)
    {
        SCOPED_CONTEXT("source (" + ost_test::detail::exact_float(row.source_sf1) + ", " + ost_test::detail::exact_float(row.source_sf2) + ") target (" +
                       ost_test::detail::exact_float(row.target_sf1) + ", " + ost_test::detail::exact_float(row.target_sf2) + ")");
        check_same_double(position_rescale_factor_between_page_scales(scale(row.source_sf1, row.source_sf2), scale(row.target_sf1, row.target_sf2)), row.factor);
    }
}

// The two ratio rules differ ON PURPOSE (plan 4.10, register SS-4): for the pair (0, 12) the strict rule has no units while the lenient one has ratio 1;
// for (1, 0) the strict rule has none and the lenient one 0. A caller that mixes them up writes the wrong factor.
TEST(SetScale_Transform, TheStrictAndTheLenientRuleDifferOnPurpose)
{
    CHECK_FALSE(units_per_sheet_inch(0.0, 12.0).has_value());
    CHECK_EQ(page_scale_ratio(0.0, 12.0), 1.0);
    CHECK_FALSE(units_per_sheet_inch(1.0, 0.0).has_value());
    CHECK_EQ(page_scale_ratio(1.0, 0.0), 0.0);
    // the pinned Windows oracle (0, 12) -> (0.25, 12) = 48 only exists for the lenient rule; the strict units of the SOURCE do not exist
    CHECK_EQ(position_rescale_factor_between_page_scales(scale(0.0, 12.0), scale(0.25, 12.0)), 48.0);
}

// ---- the epsilon -----------------------------------------------------------------------------------------------------------------------

// tests/infrastructure/mdb/components/test_page_operations.py:1957 test_rescale_threshold_is_exclusive_at_the_epsilon_itself: factor exactly 1.5 (96 -> 144),
// epsilon 0.5 gives no rewrite, epsilon 0.4999 a rewrite. The C++ epsilon is a parameter instead of a patched constant.
TEST(SetScale_Epsilon, TheThresholdIsExclusiveAtTheEpsilonItself)
{
    const double factor = units(0.125, 18.0) / units(0.125, 12.0); // 144 / 96
    CHECK_EQ(factor, 1.5);
    CHECK_FALSE(factor_needs_rescale(factor, 0.5));
    CHECK(factor_needs_rescale(factor, 0.4999));
}

// tests/infrastructure/mdb/components/test_page_operations.py:1938 test_scale_change_below_the_epsilon_does_not_rewrite_content (the rule): a factor within 1e-9 of 1
// does not rewrite, one beyond it does, 1 itself does not, NaN never does.
TEST(SetScale_Epsilon, TheDefaultEpsilonIsOneNanoAndCompareExclusive)
{
    CHECK_EQ(kScaleEpsilon, 1e-9);
    CHECK_FALSE(factor_needs_rescale(1.0));
    CHECK_FALSE(factor_needs_rescale(1.0 + 1e-12));
    CHECK_FALSE(factor_needs_rescale(1.0 - 1e-12));
    CHECK(factor_needs_rescale(1.0 + 1e-6));
    CHECK(factor_needs_rescale(1.0 - 1e-6));
    CHECK(factor_needs_rescale(2.0));
    CHECK(factor_needs_rescale(0.0));
    CHECK_FALSE(factor_needs_rescale(kNotANumber));
    // exactly at an epsilon that is representable: |1.25 - 1| == 0.25, exclusive
    CHECK_FALSE(factor_needs_rescale(1.25, 0.25));
    CHECK(factor_needs_rescale(1.25, 0.2499999));
}

// The ratio of (0.125, 12) -> (0.125, 12 * (1 + 1e-12)) is within the epsilon: the factor the store computes from units_per_sheet_inch does not need a rescale.
TEST(SetScale_Epsilon, AChangeOfOnePartInATrillionNeedsNoRescale)
{
    const double factor = units(0.125, 12.0 * (1 + 1e-12)) / units(0.125, 12.0);
    CHECK_FALSE(factor_needs_rescale(factor));
    CHECK(std::isfinite(factor)); // (a missing answer from units_per_sheet_inch is NaN here, which never needs a rescale: the factor itself must be a number)
    CHECK(factor > 0.999999999 && factor < 1.000000001);
}

// ---- the annotation rotation rule ------------------------------------------------------------------------------------------------------

// annotation.py:20-27 annotation_rotation_index for every kind and every length 0..9 (oracle: the real function).
TEST(SetScale_Rotation, RotationIndexMatchesWindowsForEveryKindAndLength)
{
    const AnnotationKind kinds[13] = {AnnotationKind::Arrow, AnnotationKind::Callout,   AnnotationKind::Cloud,   AnnotationKind::Dimension, AnnotationKind::Highlight,
                                      AnnotationKind::Hotlink, AnnotationKind::Ink,     AnnotationKind::Line,    AnnotationKind::NamedView, AnnotationKind::Oval,
                                      AnnotationKind::Polygon, AnnotationKind::Rect,    AnnotationKind::Text};
    for (int k = 0; k < 13; ++k)
    {
        for (int length = 0; length < 10; ++length)
        {
            SCOPED_CONTEXT("kind " + std::to_string(k) + " length " + std::to_string(length));
            const optional<size_t> got = annotation_rotation_index(kinds[k], vector<double>(static_cast<size_t>(length), 1.0));
            const int expected = scale_oracle::kRotationIndex[k * 10 + length];
            CHECK_EQ(got.has_value(), expected >= 0);
            if (got.has_value() && expected >= 0)
                CHECK_EQ(*got, static_cast<size_t>(expected));
        }
    }
}

// annotation_storage.py:18-40: the 13 exact-value tables and their kinds; every other table is not an annotation table.
TEST(SetScale_Rotation, TheThirteenAnnotationTablesAndNoOthers)
{
    const AnnotationKind kinds[13] = {AnnotationKind::Arrow, AnnotationKind::Callout,   AnnotationKind::Cloud,   AnnotationKind::Dimension, AnnotationKind::Highlight,
                                      AnnotationKind::Hotlink, AnnotationKind::Ink,     AnnotationKind::Line,    AnnotationKind::NamedView, AnnotationKind::Oval,
                                      AnnotationKind::Polygon, AnnotationKind::Rect,    AnnotationKind::Text};
    for (const scale_oracle::KindTable &row : scale_oracle::kKindTables)
    {
        SCOPED_CONTEXT(std::string("table ") + row.table);
        const optional<AnnotationKind> kind = annotation_kind_for_table(row.table);
        REQUIRE(kind.has_value());
        CHECK(*kind == kinds[row.kind]);
    }
    for (const char *other : {"BidTakeoffs", "BidComments", "BidTypGroupViews", "BidLegends", "BidPages", "bidtexts", "BidTexts ", ""})
    {
        SCOPED_CONTEXT(std::string("table '") + other + "'");
        CHECK_FALSE(annotation_kind_for_table(other).has_value());
    }
}

// The rotation slot keeps its value in the annotation twin: ink keeps index 0 of an odd length, text keeps from index 4 to the end, the others keep the last
// index of an odd length. (test_page_operations.py:1058 / :1080 pin the same rule on the stored text: see test_page_scale_text.cpp.)
TEST(SetScale_Rotation, TheRotationSlotKeepsItsValueWhenAnAnnotationIsRescaled)
{
    CHECK_EQ(rescale_annotation_position_between_page_scales(AnnotationKind::Ink, {0.5, 10, 20, 30, 40}, scale(1, 1), scale(1, 2)),
             vector<double>({0.5, 20, 40, 60, 80}));
    CHECK_EQ(rescale_annotation_position_between_page_scales(AnnotationKind::Text, {1, 2, 3, 4, 0.5, 9, 10}, scale(1, 1), scale(1, 2)),
             vector<double>({2, 4, 6, 8, 0.5, 9, 10}));
    CHECK_EQ(rescale_annotation_position_between_page_scales(AnnotationKind::Polygon, {0, 0, 10, 0, 10, 10, 0.7}, scale(1, 1), scale(1, 3)),
             vector<double>({0, 0, 30, 0, 30, 30, 0.7}));
    CHECK_EQ(rescale_annotation_position_between_page_scales(AnnotationKind::Line, {1, 2, 3, 4}, scale(1, 1), scale(1, 3)), vector<double>({3, 6, 9, 12}));
}

// ---- the 17 tables ---------------------------------------------------------------------------------------------------------------------

// constants.py:83-121 (PAGE_CONTENT_TABLES) + page_operations.py:26 ("BidTypGroupViews"): the Windows order of the rewrite. The store rewrites them in this order,
// so a failure in a late table must roll back the early ones (the store test blocks the last table).
TEST(SetScale_Tables, TheSeventeenPositionTablesAreInTheWindowsOrder)
{
    const vector<std::string> expected = {"BidTakeoffs",          "BidDimensions",      "BidALines",           "BidArrows",         "BidHighlights",
                                          "BidTexts",             "BidCallOuts",        "BidAnnotationRects",  "BidAnnotationOvals", "BidAnnotationPolygons",
                                          "BidAnnotationClouds",  "BidAnnoInk",         "BidLegends",          "BidComments",        "BidNamedViews",
                                          "BidHotLinks",          "BidTypGroupViews"};
    CHECK_EQ(page_position_tables(), expected);
    CHECK_EQ(page_position_tables().size(), static_cast<size_t>(17));
}
